public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    // 宇宙人の人数
    int N = sc.nextInt();
    // 消毒液が消毒できる手の数
    int M = sc.nextInt();

    int[] H = new int[N];
    for (int i = 0; i < N; i++) {
        H[i] = sc.nextInt();
    }

    int counter = 0;
    for (int i = 0; i < N; i++) {
        if (M >= H[i]) {
            M -= H[i];
            counter++;
        } else {
            break;
        }
    }
    System.out.println(counter);
}
